#!/usr/bin/env python3
"""Transfer only reviewed public payload to a new exclusive root-private cache."""
import base64, hashlib, json, os, pathlib, re, stat, sys, time
HASHES = {'apple_renewal.py': '810d3cb8fc618b70c8bb4a8e05c3306753ea4dba9d5515cf0ec20aa19b08ee23', 'apple_cleanup_renewal.py': '7bd0458b3989c3b394e302d78e2b2e29619abb0d86cbc37a70903b1e0c5b97e6', 'apple_cleanup_bootstrap.py': '9584809bac8309f2b8f1045299864fbfdb5a6921cecd6af98d254c0fd5c9c576', 'apple_cleanup_recovery.py': 'cf25b0a2b9f817bcb60c77a6c79e4930cd3be3597c3a44654c93245903b252d4', 'apple-cleanup-renewal.config.example.json': 'a369e434284d1d583999d1f0a8dfc7f8ef675869a425b6fe4a9828e3ee5e39b9', 'barber-apple-cleanup-renewal.service': '1fb39118f983bd1a8ebe36edd17882be8d134ea8ad68ac91bbf3414833ae99a2', 'barber-apple-cleanup-renewal.timer': 'd7ed645a4757b95b06aa4db77b0692d12d4bcc191ba260048c9f7fb6c168db3d', 'barber-apple-cleanup-monitor.service': 'cd0376e978b173c4e5ee67f2ff32284a9ce0a38836f22d3ef740db3631532cba', 'barber-apple-cleanup-monitor.timer': 'eebad465b2fd90662b1f6c16337305762ff1d8d30e1a0b806131ad21a800ecbc', 'apple_cleanup_inherited_pin.py': 'e9f15dd2fc26994043e70a462d9fdbaf08e96cecc762f2b7cc345c459b3fcc0d'}
PAYLOAD = {'apple_renewal.py': '', 'apple_cleanup_renewal.py': '', 'apple_cleanup_bootstrap.py': '', 'apple_cleanup_recovery.py': '', 'apple-cleanup-renewal.config.example.json': '', 'barber-apple-cleanup-renewal.service': '', 'barber-apple-cleanup-renewal.timer': '', 'barber-apple-cleanup-monitor.service': '', 'barber-apple-cleanup-monitor.timer': 'W1VuaXRdCkRlc2NyaXB0aW9uPUhvdXJseSBtZXRhZGF0YS1vbmx5IEFwcGxlIGNsZWFudXAgZXhwaXJ5IG1vbml0b3JpbmcKCltUaW1lcl0KT25DYWxlbmRhcj0qLSotKiAqOjQwOjAwIFVUQwpQZXJzaXN0ZW50PXRydWUKVW5pdD1iYXJiZXItYXBwbGUtY2xlYW51cC1tb25pdG9yLnNlcnZpY2UKCltJbnN0YWxsXQpXYW50ZWRCeT10aW1lcnMudGFyZ2V0Cg==', 'apple_cleanup_inherited_pin.py': ''}
CACHE = pathlib.Path('/etc/barber-release/apple-cleanup-setup-public-inherited-pin-v1')
def transfer():
    if len(sys.argv)!=1 or os.geteuid()!=0 or os.uname().nodename.split('.')[0]!='srv1073968': raise ValueError('FIXED_ROOT_DB_ONLY')
    names=('BARBER_SETUP_ACTIVATED_UTC','BARBER_SETUP_STOP_UTC','BARBER_SETUP_HARD_UTC')
    if not all(re.fullmatch(r'[0-9]{10}',os.environ.get(name,'')) for name in names): raise ValueError('ACCESS_DEADLINE_PARAMETERS')
    activation,stop,hard=(int(os.environ[name]) for name in names)
    if stop!=activation+2700 or hard!=activation+3600 or not activation<=time.time()<stop: raise ValueError('ACCESS_WINDOW_BINDING')
    parent=CACHE.parent; info=parent.lstat()
    if parent.resolve()!=parent or not stat.S_ISDIR(info.st_mode) or info.st_uid!=0 or stat.S_IMODE(info.st_mode)!=0o700: raise ValueError('PRIVATE_PARENT')
    if set(HASHES)!=set(PAYLOAD) or len(HASHES)!=10: raise ValueError('EXACT_PUBLIC_PAYLOAD')
    raw={name:base64.b64decode(value,validate=True) for name,value in PAYLOAD.items()}
    for name,data in raw.items():
        if '/' in name or name.startswith('.') or len(data)>262144 or hashlib.sha256(data).hexdigest()!=HASHES[name]: raise ValueError('PUBLIC_PAYLOAD_HASH')
    os.umask(0o077); CACHE.mkdir(mode=0o700)
    for name,data in raw.items():
        if time.time()>=stop: raise ValueError('WORK_WINDOW_EXPIRED')
        descriptor=os.open(CACHE/name,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600)
        with os.fdopen(descriptor,'wb')as handle: handle.write(data);handle.flush();os.fsync(handle.fileno())
    descriptor=os.open(CACHE,os.O_RDONLY|os.O_DIRECTORY)
    try: os.fsync(descriptor)
    finally: os.close(descriptor)
    print(json.dumps({'status':'EXCLUSIVE_PUBLIC_CACHE_TRANSFERRED','files':10,'rootPrivate':True,'hashesMatch':True,'privateKeyRead':False,'runtimeChanged':False}))
if __name__=='__main__':
    try:transfer()
    except Exception as error:
        print(json.dumps({'status':'PUBLIC_TRANSFER_STOPPED','reason':type(error).__name__,'privateKeyRead':False,'runtimeChanged':False}));raise SystemExit(2)
